# Adds the Q1 results to /output/report.json (idempotent: Q1 entries are tagged and replaced).
import json
r=json.load(open('/output/report.json'))
A=lambda n,v,u=None:{'name':n,'value':v,**({'unit':u} if u else {})}
r['results']=[x for x in r['results'] if not x['quantity'].startswith('Q1:') and not x['quantity'].startswith('Raw integrated-intensity ratio HCN/HCO+')]
r['recipe']=[x for x in r['recipe'] if not x['description'].startswith('Q1:')]
B=[A('window','radio velocity 2780+-350 km/s, pbcor cubes'),A('ratio convention','brightness-temperature ratio (Rayleigh-Jeans, K km/s); HCN/HCO+ Tb ratio = flux ratio x 1.0126 at same J'),
   A('systematic','5% (same OUS) / 14% (two OUS, 2 x 10% flux scale) added in quadrature to statistical error'),A('regions','out/regions.csv (Q0 / p0001); value = mean in a disc of radius FWHM/2 around the position (point-sample values agree within 0.03)')]
def add(q,v,c,ev,t=None,u=None,unit=None,ass=B):
    d={'quantity':'Q1: '+q,'value':v,'confidence':c,'evidence':ev}
    if t:d['target']=t
    if u:d['uncertainty']=u
    if unit:d['unit']=unit
    if ass:d['assumptions']=ass
    r['results'].append(d)
E1='scripts/q1_ratios.py -> out/q1/q1_ratios.csv, out/q1/q1_matched_fluxes.csv'
add('HCN/HCO+ J=3-2 (Tb ratio) at matched 1.05" circular beam (Xb4d and Xb4b both smoothed): N vs S nucleus, Bridge, Wclump',
    'N 0.81 (Xb4d) / 0.80 (Xb4b); S 0.40 / 0.39; Bridge 0.47 / 0.48; Wclump 0.36 / 0.35. N/S = 2.0','high',E1+'; HCN and HCO+ in the same OUS, same pixel; Xb4d and Xb4b agree to <=3% (N,S,Bridge,Wclump), i.e. the Xb4b missing short spacings do not bias the ratio at the nuclei',
    'N, S, Bridge, Wclump','+-0.04 (N), +-0.02 (S, Bridge, Wclump) incl. 5% systematic; statistical <=0.01',None)
add('Pixel distribution of HCN/HCO+ 3-2 (Tb) within 0.8" of each position, S/N>5 in both lines, 1.05" beam, ~2 samples per beam (Xb4d)',
    'N median 0.775 (16-84%: 0.754-0.807, range 0.70-0.85); S 0.395 (0.376-0.425); Bridge 0.458 (0.437-0.483); Wclump 0.357 (0.305-0.373); Soutflow position 0.67 (0.62-0.79). Xb4b smoothed to 1.05" gives the same medians within 0.02 (N 0.79, S 0.38)','high','scripts/q1_maps.py -> out/q1/q1_ratio_map_stats.csv, out/q1/ratio_maps.png, ratio_map_*.npz','N, S, Bridge, Wclump, Soutflow','spread = IQR 0.03-0.12',None)
add('Dependence of the N/S contrast on beam: HCN/HCO+ 3-2 (Tb) at 1.05", 6.5" and 10" circular beams',
    'N / S: 1.05": 0.81 / 0.40 (contrast 2.0); 6.5": 0.52 / 0.43 (Xb4f), 0.51 / 0.40 (Xb4d smoothed), 0.52 / 0.42 (Xb4b smoothed) (contrast 1.2); 10": 0.46 / 0.43 (Xb4f), 0.43 / 0.38 (Xb4d) (contrast 1.07); HCN/HCO+ 2-1 at 10" (Xb55): N 0.60, S 0.56, Bridge 0.58, Wclump 0.56 (contrast 1.07). Smoothing the 1.05" data to 6.5" reproduces the Xb4f values, so the contrast is lost by beam blending (N-S 5.1"), not by a different gas excitation','high',E1+'; out/q1/q1_ratios.csv','N, S','+-0.03 (6.5"), +-0.03 (10")',None)
add('HCN/HCO+ at J=2-1, 3-2, 4-3 at the common 10" beam (N and S blended by 10%-level beam wings in Band 5; Xb55 2-1, Xb4f 3-2, Xb47 4-3), Tb ratio',
    'N: 0.60 / 0.46 / 0.33; S: 0.56 / 0.43 / 0.30; Bridge 0.58 / 0.44 / 0.32; Wclump 0.56 / 0.42 / 0.30 (J=2-1 / 3-2 / 4-3). The ratio decreases with J by a factor 1.8 from 2-1 to 4-3 in every region; N-S differences (<=0.04) are within the 14% cross-band systematic','medium',E1+' (cross-band entries carry 14% systematics)','N, S, Bridge, Wclump (10" beam)','+-0.03 (2-1, 3-2), +-0.017 (4-3)',None)
add('Ladder ratios at 10" beam in K km/s (Tb ratio; 1 = thermalised optically thick): HCN 3-2/2-1, HCO+ 3-2/2-1, HCN 4-3/3-2, HCO+ 4-3/3-2',
    'N: HCN 3-2/2-1 0.37, HCO+ 3-2/2-1 0.49, HCN 4-3/3-2 0.31, HCO+ 4-3/3-2 0.42; S: 0.35, 0.47, 0.29, 0.41; Bridge 0.36, 0.48, 0.30, 0.42; Wclump 0.35, 0.46, 0.28, 0.40; at 6.5" 4-3/3-2: HCN 0.37 (N), 0.33 (S); HCO+ 0.49 (N), 0.45 (S). All strongly sub-thermal; no N/S difference beyond the 14% systematic. Input to Q2 (RADEX)','medium',E1,'N, S, Bridge, Wclump','+-14% (cross-band flux scale) dominates',None)
add('CS 7-6 relative to HCN and HCO+ 4-3 (Tb ratio, Xb47, 6.5" and 10" beams)',
    'CS 7-6/HCN 4-3: 6.5": N 0.13, S 0.18, Bridge 0.16, Wclump 0.15, Soutflow 0.20 (+-0.03); 10": N 0.10, S 0.12, Bridge 0.11. CS 7-6/HCO+ 4-3: 0.052 (N), 0.055 (S), 0.055 (Bridge) at 6.5"; 0.034/0.036 at 10" -- identical within errors, so the CS/HCN difference N vs S is the HCN difference','medium','scripts/q1_ratios.py; CS noise from 2 short line-free windows (H2CS blend limited in p0001: <0.34 Jy/b km/s)','N, S, Bridge, Wclump','+-0.01-0.03',None)
add('SO 6_5-5_4 / HCO+ 3-2 (Tb) upper limits at matched beams (SO limit includes the CH3OH A-cluster blend caveat of p0001)',
    '1.05" Xb4d: N <0.013, S <0.020 (S 2.2 sigma, not significant), Bridge <0.027, Wclump <0.036, Soutflow <0.13; Xb4b 1.05": N <0.019, S <0.030; 6.5": Xb4f N <0.015, S <0.015, Bridge <0.013, Wclump <0.015; Xb4d <0.005-0.007 (Xb4d resolves out extended flux)','medium','scripts/q1_ratios.py','N, S, Bridge, Wclump, Soutflow','3 sigma limits',None)
add('Soutflow candidate: HCN/HCO+ 3-2 (Tb) in the S-local blue wing (2272-2572 km/s) at matched 1.05" beam (Xb4d), compared with the core and nuclei',
    'Soutflow position blue wing: 1.72+-0.29 (HCN 0.354+-0.026, HCO+ 0.208+-0.031 Jy/b km/s, 13.6 / 6.8 sigma); core window (2572-2872) at the same position 0.68+-0.04; N core 0.82, S core 0.39, Bridge 0.45, Wclump 0.38; blue wing at N, S, Bridge, Wclump not detected (<3 sigma); red wing at Soutflow not detected. The Soutflow HCN/HCO+ is 4x the S-nucleus value only in the blue wing. Whether it is an outflow remains untested (Q3)','medium','scripts/q1_wings.py -> out/q1/q1_wing_ratios.csv','Soutflow (candidate)','+-0.29',None,
    ass=B+[A('windows','S-local centre 2722 km/s, +-150 around it = core, 150-450 blue/red')])
add('Dilution of Soutflow ratio with beam: HCN/HCO+ 3-2 in the full +-350 km/s window at the Soutflow position','1.05": 0.71 (Xb4d) / 0.81 (Xb4b); 6.5": 0.33 (Xb4d) / 0.41 (Xb4f) / 0.42 (Xb4b); 10": 0.34-0.41','medium','scripts/q1_ratios.py','Soutflow (candidate)','+-0.07 (1.05"), +-0.02 (6.5")',None)
add('Disk candidate (Xb55 HCO+ 2-1 S/N>5 at r>8", 281 pixels = ~3.6 independent 10" beams): HCN/HCO+ at 2-1, 3-2, 4-3 with three zero-level treatments',
    '2-1: 0.47+-0.01 (no correction), 0.50+-0.01 (ring 14-22" level subtracted), 0.47 (null-window level); 3-2: 0.06+-0.02 / 0.27+-0.01 / 0.06; 4-3: HCN not detected (-0.5+-0.1 Jy/b km/s; HCO+ 1.5+-0.1). HCO+ 3-2/2-1 (K) = 0.27 (none, null) or 0.29 (ring) against 0.47-0.49 at the nuclei. The 2-1 ratio is robust to the zero level, the 3-2 ratio is not: the ring has a negative level (HCN 2-1 -1.23, HCO+ 2-1 -1.97, HCO+ 3-2 -1.66 Jy/b km/s) whereas line-free channels have zero level (|level|<0.03), i.e. the bowl is a property of the line-window image (spatial filtering / deconvolution), not of the baseline','low','scripts/q1_disk.py -> out/q1/q1_disk_levels.csv, q1_disk_ratios.csv. Disk is a candidate, not established (one 2-1 tracer, mask edge 8" is within 1.5 beams of N, S and NEclump); no robust disk ladder or HCN/HCO+ difference can be claimed','Disk (candidate)','see value (statistical only; zero-level choice dominates)',None,
    ass=[A('beam','10" circular; mask on 1.2" Xb55 pixels'),A('Band 5 primary beam','Gaussian HWHM 17" (gain 0.86, 0.71, 0.54, 0.38 at r=8,12,16,20"); pbcor noise per 10" beam 0.18-0.19 Jy/b km/s at r=8-24" (measured in line-free windows)')])
add('Flux recovery of the Band 6 configurations (circular apertures on the field centre, native resolution, pbcor): Xb4d/Xb4f and Xb4b/Xb4f',
    'HCO+ 3-2: Xb4d/Xb4f 0.94 (r<5"), 0.69 (r<8"), 0.53 (r<10"); Xb4b/Xb4f 0.82, 0.56, 0.34. HCN 3-2: Xb4d/Xb4f 0.93, 0.58, 0.38; Xb4b/Xb4f 0.80, 0.55, 0.23. 1.1 mm continuum: Xb4d/Xb4f 0.94, 0.71, 0.64; Xb4b/Xb4f 0.81, 0.53, 0.39. (r<3": ratios >1 are Xb4f beam spill outside the aperture.) HCN is more compact than HCO+: aperture HCN/HCO+ (Tb) r<5/8/10": Xb4f 0.47/0.43/0.40, Xb4d 0.46/0.36/0.29, Xb4b 0.46/0.42/0.27','medium','scripts/q1_fluxrec.py -> out/q1/q1_flux_recovery.csv; Xb4b limited to r<11" by the stored crop','Band 6 data','+-0.01-0.03 statistical; +-10% absolute flux scale',None,
    ass=[A('aperture','centre 156.96346,-43.90461; flux = sum(Jy/beam km/s)/beam-pixels'),A('noise','robust pixel rms of line-free windows x sqrt(N_ap/N_pix_per_beam)')])
add('Matched-beam statement for every Q1 ratio','Same-J HCN/HCO+ pairs: same OUS, same pixel grid, both cubes convolved to the same circular beam (1.05", 6.5" or 10") with the image-plane kernel of scripts/matched.py, moment-0 over +-350 km/s, brightness temperature conversion for the common beam; cross-band ladder ratios: 10" (2-1/3-2/4-3) or 6.5" (3-2/4-3). Replaces the unmatched peak-pixel ratio entry of p0001 (N 0.61/0.88/1.04 across Xb4f/Xb4d/Xb4b was a beam effect: matched values are 0.52 / 0.81 / 0.80)','high','scripts/q1_lib.py, scripts/q1_ratios.py',None,None,None,None)
r['recipe'].append({'order':len(r['recipe'])+1,'stage':'measurement','description':'Q1: matched-beam HCN/HCO+, CS, SO ratios. Moment-0 maps (VSYS 2780 +-350 km/s) from pbcor cubes, convolved to 1.05", 6.5" and 10" circular beams (Jy/beam scaled by beam-area ratio), sampled at p0001 regions; noise = robust sigma of line-free windows (quietest quartile, rescaled to the window width); ratios in Tb; wing windows; disk mask with three zero levels; aperture flux recovery across Xb4f/Xb4d/Xb4b',
 'software':'astropy, scipy.signal.fftconvolve, numpy, pandas','scripts':['/workspace/scripts/q1_lib.py','/workspace/scripts/q1_ratios.py','/workspace/scripts/q1_maps.py','/workspace/scripts/q1_wings.py','/workspace/scripts/q1_disk.py','/workspace/scripts/q1_fluxrec.py','/workspace/scripts/run_q1.sh'],
 'parameters':[{'name':'velocity window','value':'2780+-350','unit':'km/s'},{'name':'common beams','value':'1.05, 6.5, 10','unit':'arcsec'},{'name':'S/N mask for ratio maps','value':'>5 in both lines'},{'name':'systematics added','value':'5% same OUS, 14% cross-band'}]})
r['caveats']+=['Q1: ratio uncertainties are dominated by systematics (window truncation ~5%, absolute flux scale 10% per band); statistical errors are <=1% at the nuclei. Noise uses few line-free windows contaminated at times by weak lines (quietest quartile used), so faint-region limits are approximate.',
 'Q1: regions use fixed nominal positions; the N ratio varies across its sub-clumps (IQR 0.05-0.09 at 1.05"), so a different aperture centre changes N by ~0.03-0.05.',
 'Q1: the decline of HCN/HCO+ and the low 3-2/2-1, 4-3/3-2 ladder ratios at 10" mix Band 5, 6 and 7 data with different resolved-out fractions (Q6: Xb4f is the most complete Band 6 set); they should be treated as inputs to RADEX with 14% errors, not as evidence for a nuclear difference.',
 'Q1: the Xb55 2-1 "disk" may include beam wings of the nuclei and NEclump; the ring zero level (-1.2 to -2.0 Jy/b km/s) is not present in line-free channels, so the sign of the correction is uncertain.']
json.dump(r,open('/output/report.json','w'),indent=1)
print(len(r['results']),'results')
